mapper.select:
SELECT 
FROM diag_result_price_band_range
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
ORDER BY ${orderBy} ${orderType}

SELECT 
FROM diag_result_price_band_range
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
  AND band_level = #{bandLevel}
ORDER BY sales DESC, price_band_min ASC

SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion,
    price_line AS priceLine, sku, sales, snapshot_time AS snapshotTime,
    create_time AS createTime, update_time AS updateTime
FROM diag_result_price_band_line
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
ORDER BY price_line ASC

SELECT
    id, tenant_id AS tenantId, query_hash AS queryHash, data_version AS dataVersion,
    price_band_min AS priceBandMin, price_band_max AS priceBandMax, sale_price AS salePrice,
    sku, sales, sale_quantity AS saleQuantity, total_sales AS totalSales, wave_type AS waveType,
    snapshot_time AS snapshotTime, create_time AS createTime, update_time AS updateTime
FROM diag_result_price_band_point
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}
ORDER BY price_band_min ASC, sale_price ASC

